function fmtVal(v,mt){
 switch(mt.fmt){
  case 'pct': return trimNum(v,1)+'%';
  case 'ms': return Math.round(v).toLocaleString('en-US')+' ms';
  case 'int': return Math.round(v).toLocaleString('en-US');
  case 'gbps': return trimNum(v,2)+' Gbps';
  case 'compact': default: return v>=1000? trimNum(v/1000,1)+'K' : trimNum(v,Math.abs(v)<10?1:0);
 }}
function trimNum(v,d){const s=v.toFixed(d);return s.replace(/\.0+$/,'').replace(/(\.\d*?)0+$/,'$1');}
function fmtDelta(dv,mt){
 const a=Math.abs(dv);
 const unit=mt.fmt==='pct'?'%':mt.fmt==='ms'?' ms':mt.fmt==='gbps'?' Gb':'';
 const num=trimNum(a, a<10?1:0);
 return (dv>=0?'▲ ':'▼ ')+num+unit;
}
