step:
```js
function step(mt,t){
 mt.drift=Math.max(-3*mt.jitter,Math.min(3*mt.jitter,mt.drift+(rng()-0.5)*mt.jitter*0.3));
 let v=mt.base+mt.drift+(rng()*2-1)*mt.jitter*1.4;
 const sc=SCRIPT[mt.id];
 if(sc){const o=sc(t,rng); if(o!=null) v=o;}
 if(mt.shock){
   if(t<mt.shock.until) v+=mt.shock.add;
   else mt.shock=null;
 }
 const prev=mt.vals.length?mt.vals[mt.vals.length-1]:null;
 mt.vals.push(v); if(mt.vals.length>140)mt.vals.shift();
 // detect
 const st=statusOf(v,mt);
 let ev=null;
 if(st!==mt.status){
   ev={t,id:mt.id+':'+t+':st',kind:'status',from:mt.status,to:st,prev:prev??v,val:v};
   mt.status=st; mt.sinceTick=t;
 } else {
   // jump detection on rolling 30 (needs >=12 samples)
   const n=mt.vals.length;
   if(prev!=null&&n>=13){
     const w=mt.vals.slice(Math.max(0,n-31),n-1); // 30 prev samples
     const mean=w.reduce((a,b)=>a+b,0)/w.length;
     const sd=Math.sqrt(w.reduce((a,b)=>a+(b-mean)*(b-mean),0)/w.length);
     if(sd>0.25*mt.jitter && Math.abs(v-mean)>3.5*sd && Math.abs(v-prev)>1.2*mt.jitter){
       ev={t,id:mt.id+':'+t+':jp',kind:'jump',from:st,to:st,prev,val:v,sigma:(Math.abs(v-mean)/sd)};
     }
   }
 }
 if(ev){mt.events.unshift(ev); if(mt.events.length>120)mt.events.pop(); mt.lastEventTick=t;}
 return ev;
}
```
Wait — on first sample (t=0) prev null: just set status/since without event. st!==mt.status on first: mt.status init 'ok'; for down-metrics first status might be ok anyway. If st differs at t=0 (e.g., base beyond warn? none are) skip event when prev==null: adjust: if(st!==mt.status){ if(prev!=null) ev=...; mt.status=st; mt.sinceTick=t; } — for t=0 just silently adopt. Good.

Jump detection window: slice before current: vals includes current at n-1. prev = vals[n-2]. w = vals.slice(n-31, n-1) → up to 30 previous. ok.

Live shock scheduler:
```js
let nextShock=HISTORY+8+Math.floor(rng()*10);
function maybeShock(t){
 if(t<nextShock)return;
 nextShock=t+14+Math.floor(rng()*22);
 const cands=METRICS.filter(x=>x.status==='ok'&&!SCRIPT[x.id]);
 if(!cands.length)return;
 const mt=cands[Math.floor(rng()*cands.length)];
 const goCrit=rng()<0.45;
 const target=goCrit? mt.crit : mt.warn;
 const span=Math.abs(target-mt.base)||mt.jitter*8;
 let add= mt.dir==='up'? span*1.3 : -span*1.3;
 if(goCrit) add*= mt.dir==='up'?1.15:1.15; // beyond
 mt.shock={add,until:t+7+Math.floor(rng()*8)};
}
```
For dir 'up': add positive pushes past warn/crit. For 'down' metrics (cache_hit, auth_ok, redis_hit, heartbeat, cert_days): warn/crit are BELOW base; add negative. span = base - target. add = -span*1.3 → v = base - span*1.3 → below warn (or crit). Good. Sign: mt.dir==='up'? +span*1.3 : -span*1.3, then *1.15 if goCrit (crit beyond warn anyway since crit target bigger gap). Simplify: const target=goCrit?mt.crit:mt.warn; const gap=Math.abs(mt.base-target); const add=(mt.dir==='up'?1:-1)*gap*(goCrit?1.25:1.1); shock until t+7+floor(rng*8).

Edge: base near target? e.g. ws_conns base 38200, warn 60000 gap 21800 *1.25=27250 → v≈65K > warn ✓. queue_lag base 310, warn 5000: gap 4690*1.1≈5160 → 5470 warn ✓ or crit: gap 19690*1.25 ≈ 24600 → 24.9K > 20K ✓.

