  Then write and run this Node script (adjust BROWSER path to what you found):

  const puppeteer = require('puppeteer-core');
  (async () => {
    const browser = await puppeteer.launch({executablePath: BROWSER_PATH, headless: 'new', args: ['--disable-gpu']});
    const page = await browser.newPage();
    const errors = [];
    page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
    page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
    await page.setViewport({width: 1680, height: 1050});
    await page.goto('file:///E:/codex-prj/ab-worktrees/pi-matrix-r3/cell-j04-s04-a/index.html', {waitUntil: 'load'});
    await new Promise(r => setTimeout(r, 2500));
    const r1 = await page.evaluate(() => ({
      tiles: document.querySelectorAll('.tile').length,
      streamRows: document.querySelectorAll('#stream .ev').length,
      alerts: document.getElementById('stat-alerts').textContent,
      tick: document.getElementById('stat-tick').textContent,
      live: document.getElementById('live-state').textContent,
      sampleVal: document.querySelector('[data-id="http5xx_pct"] .tv').textContent,
      sampleStatus: document.querySelector('[data-id="http5xx_pct"] .t-status').textContent,
    }));
    console.log('STATE_AT_LOAD', JSON.stringify(r1));
    // click a tile -> detail must open with change log
    await page.click('[data-id="db_lag_ms"]');
    await new Promise(r => setTimeout(r, 400));
    const r2 = await page.evaluate(() => ({
      detailHidden: document.getElementById('panel-detail').hidden,
      name: document.getElementById('d-name').textContent,
      logRows: document.querySelectorAll('#d-log .ev').length,
      status: document.getElementById('d-status').textContent,
    }));
    console.log('AFTER_TILE_CLICK', JSON.stringify(r2));
    await page.screenshot({path: 'E:/codex-prj/ab-worktrees/pi-matrix-r3/cell-j04-s04-a/evidence/04-detail-db_lag-after-click.png'});
    // hover the chart -> tooltip must appear
    const box = await (await page.$('#chart')).boundingBox();
    await page.mouse.move(box.x + box.width * 0.5, box.y + box.height * 0.5);
    await new Promise(r => setTimeout(r, 300));
    const r3 = await page.evaluate(() => ({tipHidden: document.getElementById('tip').hidden, tipText: document.getElementById('tip').textContent}));
    console.log('AFTER_HOVER', JSON.stringify(r3));
    // back, then click an alert chip -> detail opens
    await page.click('#btn-back');
    await new Promise(r => setTimeout(r, 200));
    await page.click('#alert-strip .alert-chip');
    await new Promise(r => setTimeout(r, 400));
    const r4 = await page.evaluate(() => ({detailHidden: document.getElementById('panel-detail').hidden, name: document.getElementById('d-name').textContent}));
    console.log('AFTER_ALERT_CLICK', JSON.stringify(r4));
    // pause -> stream freezes
    await page.click('#btn-back');
    const t1 = await page.evaluate(() => document.getElementById('stat-tick').textContent);
    await page.click('#btn-pause');
    await new Promise(r => setTimeout(r, 2500));
    const t2 = await page.evaluate(() => document.getElementById('stat-tick').textContent);
    const paused = await page.evaluate(() => document.getElementById('live-state').textContent);
    console.log('PAUSE_TEST', JSON.stringify({t1, t2, paused, frozen: t1 === t2}));
    console.log('CONSOLE_ERRORS', JSON.stringify(errors));
    await browser.close();
  })().catch(e => { console.error('FATAL', e); process.exit(1); });

  Run it with node and report ALL output lines verbatim. If puppeteer-core will not install, report why and skip (Steps 2-6 already carry the evidence).

